  `status` enum('ACTIVE','DISABLED') COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint(20) DEFAULT NULL,
  `token_version` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_user_email` (`normalized_email`),
  UNIQUE KEY `uk_sys_user_username` (`normalized_username`),
  KEY `fk_sys_user_tenant` (`tenant_id`),
  CONSTRAINT `fk_sys_user_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `sys_tenant` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sys_user_invitation` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `version` bigint(20) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `tenant_id` bigint(20) NOT NULL,
  `accepted_at` datetime(6) DEFAULT NULL,
  `email` varchar(320) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime(6) NOT NULL,
  `role_code` enum('ADMIN','CANDIDATE','INTERVIEWER','PLATFORM_ADMIN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('ACCEPTED','PENDING','REVOKED') COLLATE utf8mb4_unicode_ci NOT NULL,
  `token_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_user_invitation_token_hash` (`token_hash`),
  KEY `fk_sys_user_invitation_tenant` (`tenant_id`),
  CONSTRAINT `fk_sys_user_invitation_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `sys_tenant` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sys_user_role` (
  `role_id` bigint(20) NOT NULL,
  `user_id` bigint(20) NOT NULL,
  PRIMARY KEY (`role_id`,`user_id`),
  KEY `FKb40xxfch70f5qnyfw8yme1n1s` (`user_id`),
  CONSTRAINT `FKb40xxfch70f5qnyfw8yme1n1s` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`),
  CONSTRAINT `FKhh52n8vd4ny9ff4x9fb8v65qx` FOREIGN KEY (`role_id`) REFERENCES `sys_role` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `tenant_agent` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `version` bigint(20) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `tenant_id` bigint(20) NOT NULL,
  `created_by_user_id` bigint(20) DEFAULT NULL,
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `enabled_tools` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL,
  `knowledge_enabled` bit(1) NOT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('ACTIVE','DISABLED') COLLATE utf8mb4_unicode_ci NOT NULL,
  `system_prompt` text COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `tenant_agent_prompt_history` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `version` bigint(20) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `tenant_id` bigint(20) NOT NULL,
  `agent_id` bigint(20) NOT NULL,
  `change_type` enum('CLEAR','ROLLBACK','SAVE') COLLATE utf8mb4_unicode_ci NOT NULL,
  `changed_by_user_id` bigint(20) DEFAULT NULL,
  `revision` int(11) NOT NULL,
  `system_prompt` text COLLATE utf8mb4_unicode_ci NOT NULL,
